var t=`0881-dal-bhat-tarkari`;var n=`world-0881`;var a=`NP`;var s=`south-asia`;var r=4;var l=85;var o={en:`Dal Bhat Tarkari`,ua:`Дал бхат таркарі`};var g={en:`Dal Bhat Tarkari is a Nepal dish made with basmati rice, red lentils, potato, cauliflower. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дал бхат таркарі, страва кухні країни Непал. Основні складники: рис басматі, червона сочевиця, картопля, цвітна капуста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`basmati-rice`,410,`g`],[`water`,820,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 26 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 26 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:26,i:[[`red-lentils`,260,`g`],[`water`,820,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 15 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 15 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:15,i:[[`potato`,370,`g`],[`cauliflower`,270,`g`],[`yellow-onion`,190,`g`],[`tomato`,250,`g`],[`canola-oil`,45,`ml`],[`ground-cumin`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 17 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 17 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:17,i:[[`water`,220,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`]]}];var u={slug:t,id:n,country:`NP`,region:s,servings:4,minutes:85,title:o,text:g,steps:d};export{a as country,u as default,n as id,l as minutes,s as region,r as servings,t as slug,d as steps,g as text,o as title};